const ChemTouchControls=(()=>{
  const key='chemicats.touch.v1',event='chem-touch-preferences',defaults={leftHanded:false,dashOffset:0,deadZone:12,radius:60};
  let value={...defaults};
  const number=(n,low,high,fallback)=>typeof n==='number'&&Number.isFinite(n)?Math.max(low,Math.min(high,n)):fallback;
  const normalize=data=>({leftHanded:data.leftHanded===true,dashOffset:number(data.dashOffset,-24,24,0),deadZone:number(data.deadZone,4,24,12),radius:number(data.radius,40,80,60)});
  try{const data=JSON.parse(localStorage.getItem(key)||'null');if(data?.version===1)value=normalize(data);}catch{}
  return Object.freeze({event,get:()=>({...value}),set(patch){
    if(!patch||typeof patch!=='object'||Array.isArray(patch)||Object.keys(patch).some(name=>!Object.hasOwn(defaults,name)))return false;
    if(ChemTrial.active||ChemBiomes.reviewActive||ChemEnding.isPreview(ChemTrial.engine))return false;
    const next=normalize({...value,...patch});
    try{const raw=JSON.stringify({version:1,...next});localStorage.setItem(key,raw);if(localStorage.getItem(key)!==raw)return false;}catch{return false;}
    value=next;window.dispatchEvent(new Event(event));return true;
  }});
})();
