const ChemReadability = (() => {
  const key='chemicats.readability.v1', defaults={textScale:1,mapScale:1};
  let value={...defaults};
  const clamp=(n,lo,hi)=>Number.isFinite(Number(n))?Math.min(hi,Math.max(lo,Number(n))):1;
  try { const data=JSON.parse(localStorage.getItem(key)||'null');
    if(data&&data.version===1)value={textScale:clamp(data.textScale,1,1.3),mapScale:clamp(data.mapScale,.8,1.25)};
  } catch {}
  function apply(){document.documentElement.style.setProperty('--chem-menu-text-scale',String(value.textScale));}
  apply();
  return Object.freeze({
    get:()=>({...value}),
    set(name,n){
      if(!Object.hasOwn(defaults,name)||ChemTrial.active||ChemBiomes.reviewActive||ChemEnding.isPreview(ChemTrial.engine))return false;
      const next={...value,[name]:name==='textScale'?clamp(n,1,1.3):clamp(n,.8,1.25)};
      try{const encoded=JSON.stringify({version:1,...next});localStorage.setItem(key,encoded);if(localStorage.getItem(key)!==encoded)return false;}catch{return false;}
      value=next;apply();return true;
    },
    mapSize(desktop){const base=desktop?Math.min(176,innerHeight*.25):Math.min(116,innerHeight*.28);
      return Math.min(base*value.mapScale,innerHeight*(desktop?.32:.34));}
  });
})();
