// This pilot relays presence only. It never applies somebody else's game world.
const ChemLAN=(()=>{
 try{localStorage.removeItem('lanActive')}catch{}
 let socket=null,engine=null,refresh=()=>{},status='offline',reason='',clientId='',nickname='Player',elapsed=0,timer=0;
 const cats=['ginger_cat','black_cat','bohr_cat','curie_cat','mendelejew'];
 const idOK=id=>typeof id==='string'&&/^[A-Za-z0-9_-]{8,32}$/.test(id);
 const finite=(n,min,max)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;
 const notify=()=>{try{refresh()}catch{}};
 function stop(error='',matching=null){
  if(matching&&engine!==matching)return false;
  const prior=socket,e=engine;socket=null;engine=null;Ta=null;clearTimeout(timer);timer=0;elapsed=0;
  status=error?'error':'offline';reason=error;
  try{prior?.close()}catch{}
  if(e)ChemLANSession.leave(e);
  notify();return true;
 }
 function connect(e,onChange=()=>{},name=chemSafeStorageRead('lanNick')||'Player'){
  stop();refresh=onChange;
  nickname=(typeof name==='string'?name:'Player').replace(/[\x00-\x1f\x7f]/g,'').trim().slice(0,24)||'Player';
  if(!e||!['http:','https:'].includes(location.protocol)||!location.host){status='error';reason='file';notify();return false}
  if(!ChemLANSession.enter(e)){status='error';reason='busy';notify();return false}
  engine=e;status='connecting';reason='';elapsed=0;
  try{
   clientId=Array.from(crypto.getRandomValues(new Uint8Array(12)),n=>n.toString(16).padStart(2,'0')).join('');
   const ws=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/play`);socket=ws;Ta=ws;
   timer=setTimeout(()=>{if(socket===ws&&status==='connecting')stop('server')},5000);
   ws.onopen=()=>{if(socket!==ws)return;elapsed=.1;tick(e,0)};
   ws.onerror=()=>{if(socket===ws)stop('server')};
   ws.onclose=()=>{if(socket===ws)stop('lost')};
   ws.onmessage=event=>{
    if(socket!==ws||engine!==e||typeof event.data!=='string'||event.data.length>4096)return;
    try{
     const m=JSON.parse(event.data);if(m.version!==1||!idOK(m.id))return;
     if(m.type==='ready'&&m.id===clientId){clearTimeout(timer);timer=0;status='connected';notify();return}
     if(m.id===clientId||status!=='connected')return;
     const players=e.state.networkPlayers;
     if(m.type==='player_leave'){e.state.networkPlayers=players.filter(p=>p.id!==m.id);notify();return}
     const p=m.state;
     if(m.type!=='state_update'||!p||p.clientId!==m.id||!p.pos||!finite(p.pos.x,-10000,10000)||!finite(p.pos.y,-10000,10000)||!cats.includes(p.char)||typeof p.nick!=='string'||p.nick.length>24||!finite(p.hp,0,1e9)||!finite(p.maxHp,1,1e9)||typeof p.isDead!=='boolean')return;
     let peer=players.find(n=>n.id===m.id);
     if(!peer){if(players.length>=3)return;peer={id:m.id,pos:{...p.pos}};players.push(peer)}
     Object.assign(peer,{targetPos:{...p.pos},char:p.char,nick:p.nick.replace(/[\x00-\x1f\x7f]/g,''),hp:p.hp,maxHp:p.maxHp,isDead:p.isDead});notify();
    }catch{}
   };
  }catch{stop('server');return false}
  notify();return true;
 }
 function tick(e,dt){
  if(engine!==e||!ChemLANSession.active(e)||!finite(dt,0,1))return;
  const k=1-Math.exp(-24*dt);
  for(const p of e.state.networkPlayers)if(p.pos&&p.targetPos){p.pos.x+=(p.targetPos.x-p.pos.x)*k;p.pos.y+=(p.targetPos.y-p.pos.y)*k}
  if(!['connecting','connected'].includes(status)||!socket||socket.readyState!==1)return;
  elapsed+=dt;if(elapsed<.1)return;elapsed%=.1;
  if(socket.bufferedAmount>8192){stop('lost');return}
  const s=e.state,p=s.player;
  try{socket.send(JSON.stringify({type:'update',version:1,state:{clientId,pos:{x:p.pos.x,y:p.pos.y},char:s.selectedCharacter,nick:nickname,hp:Math.max(0,Math.min(1e9,p.hp)),maxHp:Math.max(1,Math.min(1e9,p.maxHp)),isDead:!!p.isDead}}))}catch{stop('lost')}
 }
 function text(s){
  const en=s?.language==='en';
  if(reason==='file')return en?'Open the PC server address, not the HTML file.':'Otwórz adres serwera na PC zamiast pliku HTML.';
  if(reason==='busy')return en?'Finish the current preview or test first.':'Najpierw zakończ bieżący podgląd lub test.';
  if(reason==='server')return en?'LAN server unavailable. Your offline game is restored.':'Serwer LAN niedostępny. Przywrócono grę offline.';
  if(reason==='lost')return en?'Disconnected. Your offline game is restored.':'Rozłączono. Przywrócono grę offline.';
  return en?({offline:'Offline',connecting:'Connecting…',connected:'Connected · presence only'}[status]):({offline:'Offline',connecting:'Łączenie…',connected:'Połączono · tylko obecność'}[status]);
 }
 return {connect,disconnect:(matching=null)=>stop('',matching),tick,text,get status(){return status},get clientId(){return clientId}};
})();

