/* CHEM-ELECTRIC-HOOKS-V1: event-only physics, vector world overlay; no saved effect state. */
const ChemElectricHooks = (() => {
  const FX = globalThis.ChemElectricFX;
  const Electric = globalThis.ChemElectric;
  if (!FX || !Electric) throw new Error('Electricity modules must be loaded before their hooks.');

  let boundState = null, boundRooms = null, roomX = null, roomY = null;
  function syncEffects(state) {
    const x = state?.currentRoom?.x, y = state?.currentRoom?.y;
    if (state !== boundState || state?.rooms !== boundRooms || x !== roomX || y !== roomY || state?.player?.isDead || state?.state === 'gameover') {
      FX.clear(); Electric.reset();
      boundState = state; boundRooms = state?.rooms; roomX = x; roomY = y;
    }
  }

  // U6 is the shared family-effect function: both atoms and bound compounds use it.
  // Intercept before native conductor damage so the new bounded propagation never doubles damage.
  const nativeFamilyEffect = U6;
  U6 = function(state, target, origin, family, params, count = 1) {
    if (family === 'conductor') { syncEffects(state); return Electric.conduct(state, target, origin, params, count); }
    return nativeFamilyEffect.call(this, state, target, origin, family, params, count);
  };

  // Keep effect time on the same game update and freeze it behind existing panels.
  const nativeUpdate = Y6.prototype.update;
  Y6.prototype.update = function(dt) {
    syncEffects(this.state); FX.tick(this, dt); Electric.tick(this, dt);
    try { return nativeUpdate.call(this, dt); }
    finally { syncEffects(this.state); }
  };

  // One mutable record per actual renderer. No new object or copied view is allocated per frame.
  const renderFrames = new WeakMap();
  const nativeBegin = ay.prototype.begin;
  ay.prototype.begin = function(state, view) {
    syncEffects(state);
    let frame = renderFrames.get(this);
    if (!frame) {
      frame = {state: null, view: {x: 0, y: 0, w: 0, h: 0}};
      renderFrames.set(this, frame);
    }
    frame.state = state;
    frame.view.x = view.x;
    frame.view.y = view.y;
    frame.view.w = view.w;
    frame.view.h = view.h;
    return nativeBegin.call(this, state, view);
  };

  // Called after world bodies/death ghosts, before the screen-space enemy labels and player/HUD.
  // Retain every earlier ghost/reaction wrapper and use the exact material's current quality.
  const nativeGhosts = ChemTrial.renderGhosts;
  ChemTrial.renderGhosts = function(ctx, dt, active, material) {
    const result = nativeGhosts.call(this, ctx, dt, active, material);
    const frame = material && renderFrames.get(material);
    if (frame) FX.draw(ctx, frame.state, material.quality, frame.view);
    return result;
  };

  return Object.freeze({installed: true, version: 1});
})();
globalThis.ChemElectricHooks = ChemElectricHooks;

