function ChemCharacterIdentityCard({id,en}){const values=(ChemCharacterIdentity[id]||ChemCharacterIdentity.ginger_cat)[en?1:0],labels=en?['Range','Strength','Weakness','Families after discovery']:['Dystans','Mocna strona','Słabość','Rodziny po odkryciu'];return c.jsx('div',{'data-character-profile':id,style:{fontSize:12,lineHeight:1.35,textAlign:'left',color:'#cbd5e1'},children:values.map((value,index)=>c.jsxs('p',{style:{margin:'3px 0'},children:[c.jsx('strong',{style:{color:index===2?'#fcd5ab':'#93d9e9'},children:labels[index]+': '}),value]},index))})}
